    "inputSourceName": "project/contracts/helpers/GenericHarvester.sol",
    "devdoc": {
      "author": "Cooper Labs",
      "custom:contact": "security@cooperlabs.xyz",
      "details": "Generic contract for anyone to permissionlessly adjust the reserves of Angle ParallelizerThis contract is an authorized fork of Angle's GenericHarvester contract: https://github.com/AngleProtocol/angle-transmuter/blob/main/contracts/helpers/GenericHarvester.sol",
      "errors": {
        "SafeERC20FailedOperation(address)": [
          {
            "details": "An operation with an ERC-20 token failed."
          }
        ]
      },
      "events": {
        "AuthorityUpdated(address)": {
          "details": "Authority that manages this contract was updated."
        }
      },
      "kind": "dev",
      "methods": {
        "addBudget(uint256,address)": {
          "params": {
            "amount": "amount of tokenP to add to the budget",
            "receiver": "address of the receiver"
          }
        },
        "authority()": {
          "details": "Returns the current authority."
        },
        "computeRebalanceAmount(address)": {
          "params": {
            "yieldBearingAsset": "address of the yield bearing asset"
          },
          "returns": {
            "amount": "amount to be rebalanced",
            "increase": "whether the exposure should be increased"
          }
        },
        "harvest(address,uint256,bytes)": {
          "details": "This transaction either reduces the exposure to `yieldBearingAsset` in the Parallelizer or frees up some yieldBearingAsset that can then be used for people looking to burn deposit tokensDue to potential transaction fees within the Parallelizer, this function doesn't exactly bring `yieldBearingAsset` to the target exposurescale is a number between 0 and 1e9 that represents the proportion of the tokenP to harvest, it is used to lower the amount of the asset to harvest for example to have a lower slippage"
        },
        "isConsumingScheduledOp()": {
          "details": "Returns true only in the context of a delayed restricted call, at the moment that the scheduled operation is being consumed. Prevents denial of service for delayed restricted calls in the case that the contract performs attacker controlled calls."
        },
        "onFlashLoan(address,address,uint256,uint256,bytes)": {
          "details": "Receive a flash loan.",
          "params": {
            "amount": "The amount of tokens lent.",
            "data": "Arbitrary data structure, intended to contain user-defined parameters.",
            "fee": "The additional amount of tokens to repay.",
            "initiator": "The initiator of the loan.",
            "token": "The loan currency."
          },
          "returns": {
            "_0": "The keccak256 hash of \"ERC3156FlashBorrower.onFlashLoan\""
          }
        },
        "recoverERC20(address,uint256,address)": {
          "params": {
            "amountToRecover": "amount to recover",
            "to": "address to send the recovered tokens",
            "tokenAddress": "address of the token to recover"
          }
        },
        "removeBudget(uint256,address)": {
          "params": {
            "amount": "amount of tokenP to remove from the budget",
            "receiver": "address of the receiver"
          }
        },
        "setAuthority(address)": {
          "details": "Transfers control to a new authority. The caller must be the current authority."
        },
        "setMaxSlippage(address,uint96)": {
          "params": {
            "newMaxSlippage": "new max allowed slippage"
          }
        },
        "setSwapRouter(address)": {
          "params": {
            "newSwapRouter": "address of the swap router"
          }
        },
        "setTargetExposure(address,uint64)": {
          "params": {
            "targetExposure": "target exposure to the yield bearing asset used",
            "yieldBearingAsset": "address of the yield bearing asset"
          }
        },
        "setTokenTransferAddress(address)": {
          "params": {
            "newTokenTransferAddress": "address of the token transfer contract"
          }
        },
        "setYieldBearingAssetData(address,address,uint64,uint64,uint64,uint64,uint96)": {
          "params": {
            "asset": "address of the asset",
            "maxExposure": "maximum exposure within the Parallelizer to the asset",
            "minExposure": "minimum exposure within the Parallelizer to the asset",
            "overrideExposures": "whether limit exposures should be overriden or read onchain through the Parallelizer",
            "targetExposure": "target exposure to the yieldBearingAsset asset used",
            "yieldBearingAsset": "address of the yieldBearingAsset"
          }
        },
        "toggleTrusted(address)": {
          "params": {
            "trusted": "address to toggle the trusted status"
          }
        },
        "updateLimitExposuresYieldAsset(address)": {
          "params": {
            "yieldBearingAsset": "address of the yield bearing asset"
          }
        }
      },
      "title": "GenericHarvester",
      "version": 1
    },
