    "inputSourceName": "project/contracts/helpers/MultiBlockHarvester.sol",
    "devdoc": {
      "author": "Cooper Labs",
      "custom:contact": "security@cooperlabs.xyz",
      "details": "Contract to harvest yield from multiple yield bearing assets in multiple blocks transactionsThis contract is an authorized fork of Angle's MultiBlockHarvester contract: https://github.com/AngleProtocol/angle-transmuter/blob/main/contracts/helpers/MultiBlockHarvester.sol",
      "errors": {
        "SafeERC20FailedOperation(address)": [
          {
            "details": "An operation with an ERC-20 token failed."
          }
        ]
      },
      "events": {
        "AuthorityUpdated(address)": {
          "details": "Authority that manages this contract was updated."
        }
      },
      "kind": "dev",
      "methods": {
        "authority()": {
          "details": "Returns the current authority."
        },
        "computeRebalanceAmount(address)": {
          "params": {
            "yieldBearingAsset": "address of the yield bearing asset"
          },
          "returns": {
            "amount": "amount to be rebalanced",
            "increase": "whether the exposure should be increased"
          }
        },
        "finalizeRebalance(address,uint256)": {
          "params": {
            "yieldBearingAsset": "address of the yieldBearingAsset"
          }
        },
        "harvest(address,uint256,bytes)": {
          "params": {
            "scale": "scale to apply to the rebalance amount",
            "yieldBearingAsset": "address of the yieldBearingAsset"
          }
        },
        "isConsumingScheduledOp()": {
          "details": "Returns true only in the context of a delayed restricted call, at the moment that the scheduled operation is being consumed. Prevents denial of service for delayed restricted calls in the case that the contract performs attacker controlled calls."
        },
        "recoverERC20(address,uint256,address)": {
          "params": {
            "amountToRecover": "amount to recover",
            "to": "address to send the recovered tokens",
            "tokenAddress": "address of the token to recover"
          }
        },
        "setAuthority(address)": {
          "details": "Transfers control to a new authority. The caller must be the current authority."
        },
        "setMaxSlippage(address,uint96)": {
          "params": {
            "newMaxSlippage": "new max allowed slippage"
          }
        },
        "setTargetExposure(address,uint64)": {
          "params": {
            "targetExposure": "target exposure to the yield bearing asset used",
            "yieldBearingAsset": "address of the yield bearing asset"
          }
        },
        "setYieldBearingAssetData(address,address,uint64,uint64,uint64,uint64,uint96)": {
          "params": {
            "asset": "address of the asset",
            "maxExposure": "maximum exposure within the Parallelizer to the asset",
            "minExposure": "minimum exposure within the Parallelizer to the asset",
            "overrideExposures": "whether limit exposures should be overriden or read onchain through the Parallelizer",
            "targetExposure": "target exposure to the yieldBearingAsset asset used",
            "yieldBearingAsset": "address of the yieldBearingAsset"
          }
        },
        "setYieldBearingToDepositAddress(address,address)": {
          "params": {
            "newDepositAddress": "address to deposit to receive yieldBearingAsset",
            "yieldBearingAsset": "address of the yieldBearingAsset"
          }
        },
        "toggleTrusted(address)": {
          "params": {
            "trusted": "address to toggle the trusted status"
          }
        },
        "updateLimitExposuresYieldAsset(address)": {
          "params": {
            "yieldBearingAsset": "address of the yield bearing asset"
          }
        }
      },
      "title": "MultiBlockHarvester",
      "version": 1
    },
