    "devdoc": {
      "author": "Cooper Labs",
      "custom:contact": "security@cooperlabs.xyz",
      "details": "This interface is an authorized fork of Angle's `ITransmuter` interface https://github.com/AngleProtocol/angle-transmuter/blob/main/contracts/interfaces/ITransmuter.sol",
      "kind": "dev",
      "methods": {
        "diamondCut((address,uint8,bytes4[])[],address,bytes)": {
          "params": {
            "_calldata": "A function call, including function selector and arguments, executed with delegatecall on _init",
            "_diamondCut": "Contains the facet addresses and function selectors",
            "_init": "The address of the contract or facet to execute _calldata"
          }
        },
        "facetAddress(bytes4)": {
          "details": "If facet is not found return address(0).",
          "params": {
            "_functionSelector": "The function selector."
          },
          "returns": {
            "facetAddress_": "The facet address."
          }
        },
        "facetAddresses()": {
          "returns": {
            "facetAddresses_": "facetAddresses_"
          }
        },
        "facetFunctionSelectors(address)": {
          "params": {
            "_facet": "The facet address."
          },
          "returns": {
            "facetFunctionSelectors_": "facetFunctionSelectors_"
          }
        },
        "facets()": {
          "returns": {
            "facets_": "Facet"
          }
        },
        "getCollateralSurplus(address)": {
          "params": {
            "collateral": "The collateral address to compute the surplus of."
          },
          "returns": {
            "collateralSurplus": "The collateral surplus amount.",
            "stableSurplus": "The surplus in stable amount."
          }
        },
        "getOracle(address)": {
          "returns": {
            "oracleData": "Extra data needed to read the oracle. For Chainlink oracles, this data is supposed to give the addresses of the Chainlink feeds to read, the stale periods for each feed, ...",
            "oracleType": "Type of oracle (Chainlink, external smart contract, ...)",
            "targetData": "Extra data needed to read the target price of the asset",
            "targetType": "Type passed to read the value of the target price"
          }
        },
        "getOracleValues(address)": {
          "returns": {
            "burn": "Oracle value that will be used for `collateral` for a burn transaction. This value is then used along with oracle values for all other collateral assets to get a global burn value for the oracle",
            "minRatio": "Minimum ratio across all collateral assets between a collateral burn price and its target price. This value is independent of `collateral` and is used to normalize the burn oracle value for burn transactions.",
            "mint": "Oracle value to be used for a mint transaction with `collateral`",
            "ratio": "Ratio, in base `10**18` between the oracle value of the `collateral` and its target price. This value is 10**18 if the oracle is greater than the collateral price",
            "redemption": "Oracle value that would be used to price `collateral` when computing the collateral ratio during a redemption"
          }
        },
        "getSlippageTolerance(address)": {
          "details": "Maximum slippage tolerance is 1e9 (100%)"
        },
        "isConsumingScheduledOp()": {
          "details": "Returns true only in the context of a delayed restricted call, at the moment that the scheduled operation is being consumed. Prevents denial of service for delayed restricted calls in the case that the contract performs attacker controlled calls."
        },
        "isWhitelistedForType(uint8,address)": {
          "details": "Note that ultimately whitelisting may depend as well on external providers"
        },
        "processSurplus(address)": {
          "details": "This function will swap the surplus of a collateral for the stable asset link to the protocol.",
          "params": {
            "collateral": "The collateral address to process the surplus of."
          },
          "returns": {
            "collateralSurplus": "The surplus of the collateral.",
            "issuedAmount": "The amount of newly issued stablecoins from the collateral swapped",
            "stableSurplus": "The surplus amount in stable calculated from the collateral surplus."
          }
        },
        "quoteRedemptionCurve(uint256)": {
          "returns": {
            "amounts": "Amount that would be obtained for each token in the `tokens` array",
            "tokens": "List of tokens that would be given"
          }
        },
        "redeem(uint256,address,uint256,uint256[])": {
          "params": {
            "deadline": "Timestamp before which the redemption should have occured",
            "minAmountOuts": "Minimum amount of each token given back in the redemption to obtain",
            "receiver": "Address which should be receiving the output tokens"
          },
          "returns": {
            "amounts": "Amount given for each token in the `tokens` array",
            "tokens": "List of tokens returned"
          }
        },
        "release()": {
          "returns": {
            "amounts": "The amounts released to the payees",
            "payees": "The addresses of the payees"
          }
        },
        "revokeCollateral(address,bool)": {
          "details": "If `checkExternalManagerBalance` is true, the function will check that the current manager no longer has assets before revoking the collateral"
        },
        "sellRewards(uint256,bytes)": {
          "params": {
            "minAmountOut": "Minimum amount of the outToken to get",
            "payload": "Payload to pass to odos"
          },
          "returns": {
            "amountOut": "Amount obtained of the outToken"
          }
        },
        "setCollateralManager(address,bool,(address[],bytes))": {
          "details": "If `checkExternalManagerBalance` is true, the function will check that the current manager no longer has assets before setting the new manager"
        },
        "swapExactInput(uint256,uint256,address,address,address,uint256)": {
          "params": {
            "amountIn": "Amount of `tokenIn` to bring",
            "amountOutMin": "Minimum amount of `tokenOut` to get: if `amountOut` is inferior to this amount, the function will revert",
            "deadline": "Timestamp before which the transaction must be executed",
            "to": "Address to which `tokenOut` must be sent",
            "tokenIn": "Token to bring for the swap",
            "tokenOut": "Token to get out of the swap"
          },
          "returns": {
            "amountOut": "Amount of `tokenOut` obtained through the swap"
          }
        },
        "swapExactInputWithPermit(uint256,uint256,address,address,uint256,bytes)": {
          "details": "Can only be used to mint, hence `tokenOut` is not needed"
        },
        "swapExactOutput(uint256,uint256,address,address,address,uint256)": {
          "params": {
            "amountInMax": "Maximum amount of `tokenIn` to bring in order to get `amountOut` of `tokenOut`",
            "amountOut": "Amount of `tokenOut` to obtain from the swap",
            "deadline": "Timestamp before which the transaction must be executed",
            "to": "Address to which `tokenOut` must be sent",
            "tokenIn": "Token to bring for the swap",
            "tokenOut": "Token to get out of the swap"
          },
          "returns": {
            "amountIn": "Amount of `tokenIn` used to perform the swap"
          }
        },
        "swapExactOutputWithPermit(uint256,uint256,address,address,uint256,bytes)": {
          "details": "Can only be used to mint, hence `tokenOut` is not needed"
        },
        "updateSlippageTolerance(address,uint256)": {
          "details": "Maximum slippage tolerance is 1e9 (100%)The slippage tolerance is used to compute the minimum expected amount of stablecoins to be received when calling the `processSurplus` function"
        }
      },
      "title": "IParallelizer",
      "version": 1
    },
